\"\"\"Send private text prompts to OpenAI's Responses API using the standard library.\"\"\"

from __future__ import annotations

import json
import os
import ssl
import urllib.error
import urllib.request
from typing import Any, Mapping


API_URL = \"https://api.openai.com/v1/responses\"
DEFAULT_MODEL = \"gpt-4.1\"


class OpenAIAPIError(RuntimeError):
    def __init__(
        self,
        message: str,
        status: int | None = None,
        payload: Any = None,
    ) -> None:
        super().__init__(message)
        self.status = status
        self.payload = payload


class OpenAIClient:
    \"\"\"HTTPS client for the Responses API. Prompts are not persisted by default.\"\"\"

    def __init__(
        self,
        api_key: str | None = None,
        *,
        model: str = DEFAULT_MODEL,
        timeout: float = 60.0,
        api_url: str = API_URL,
    ) -> None:
        key = api_key if api_key is not None else os.environ.get(\"OPENAI_API_KEY\")
        if not key:
            raise ValueError(\"Set OPENAI_API_KEY or pass api_key\")
        self.api_key = key
        self.model = model
        self.timeout = timeout
        self.api_url = api_url
        self._ssl_context = ssl.create_default_context()

    def send_prompt(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        store: bool = False,
        extra: Mapping[str, Any] | None = None,
    ) -> str:
        if not isinstance(prompt, str) or not prompt.strip():
            raise ValueError(\"prompt must be a non-empty string\")
        body: dict[str, Any] = {
            \"model\": model or self.model,
            \"input\": prompt,
            \"store\": store,
        }
        if instructions is not None:
            body[\"instructions\"] = instructions
        if extra:
            body.update(dict(extra))
        return extract_output_text(self._post(body))

    def create_response(self, **kwargs: Any) -> dict[str, Any]:
        if \"model\" not in kwargs:
            kwargs[\"model\"] = self.model
        if \"store\" not in kwargs:
            kwargs[\"store\"] = False
        return self._post(kwargs)

    def _post(self, body: Mapping[str, Any]) -> dict[str, Any]:
        payload = json.dumps(body).encode(\"utf-8\")
        request = urllib.request.Request(
            self.api_url,
            data=payload,
            method=\"POST\",
            headers={
                \"Authorization\": f\"Bearer {self.api_key}\",
                \"Content-Type\": \"application/json\",
                \"Accept\": \"application/json\",
            },
        )
        try:
            with urllib.request.urlopen(
                request,
                timeout=self.timeout,
                context=self._ssl_context,
            ) as response:
                raw = response.read()
        except urllib.error.HTTPError as exc:
            detail = _decode_error_payload(exc.read())
            raise OpenAIAPIError(
                f\"Responses API request failed with HTTP {exc.code}\",
                status=exc.code,
                payload=detail,
            ) from None
        except urllib.error.URLError as exc:
            raise OpenAIAPIError(
                f\"Responses API request failed: {exc.reason}\"
            ) from None
        try:
            data = json.loads(raw.decode(\"utf-8\"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise OpenAIAPIError(\"Responses API returned invalid JSON\") from exc
        if not isinstance(data, dict):
            raise OpenAIAPIError(\"Responses API returned an unexpected payload\")
        return data


def extract_output_text(response: Mapping[str, Any]) -> str:
    text = response.get(\"output_text\")
    if isinstance(text, str) and text:
        return text
    chunks: list[str] = []
    for item in response.get(\"output\") or []:
        if not isinstance(item, Mapping):
            continue
        for content in item.get(\"content\") or []:
            if not isinstance(content, Mapping):
                continue
            if content.get(\"type\") in {\"output_text\", \"text\"} and isinstance(
                content.get(\"text\"), str
            ):
                chunks.append(content[\"text\"])
    return \"\".join(chunks)


def send_private_prompt(prompt: str, **kwargs: Any) -> str:
    client_kwargs = {
        key: kwargs.pop(key)
        for key in (\"api_key\", \"timeout\", \"api_url\")
        if key in kwargs
    }
    model = kwargs.pop(\"model\", None)
    if \"model\" not in client_kwargs and model is not None:
        client_kwargs[\"model\"] = model
    return OpenAIClient(**client_kwargs).send_prompt(prompt, model=model, **kwargs)


def _decode_error_payload(raw: bytes) -> Any:
    if not raw:
        return None
    try:
        return json.loads(raw.decode(\"utf-8\"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None
